const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');await p.evaluate(()=>{const j=DEUTSCH_JOURNEY;for(const i of [0,1]){j.select(i);profileStorage.setItem(j.key,JSON.stringify({version:1,lessons:{},final:{passed:true,best:100}}))}profileStorage.setItem(DEUTSCH_FOX_CONVERSATION.key,JSON.stringify({completed:true}));j.select(0);sessionStorage.setItem('storyGrades',JSON.stringify([profileStorage.getItem('deutsch16_journey_v1'),profileStorage.getItem('deutsch16_journey_village_v1')]))});
await p.click('#expeditionSail');if(await p.locator('dialog[open][data-story-scene="voyage"]').count()!==1)throw Error('Missing voyage');if(await p.locator('#storySceneSkip').evaluate(e=>document.activeElement!==e))throw Error('Skip has no initial focus');await p.click('#storySceneSkip');if(await p.evaluate(()=>DEUTSCH_JOURNEY.island)!==1)throw Error('Skipped voyage failed handoff');await p.click('#lighthouseCelebrate');if(await p.locator('dialog[open][data-story-scene="lighthouse"]').count()!==1||await p.locator('.story-residents img').count()!==6)throw Error('Missing lighthouse celebration');await p.keyboard.press('Escape');if(await p.locator('dialog[open]').count()||await p.locator('.is-lighthouse-lit').count()!==1)throw Error('Escape lost lighthouse');
fs.mkdirSync('audit-screenshots',{recursive:true});for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});await p.click('#lighthouseCelebrate');await p.locator('.story-scene img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));if(await p.locator('.story-scene').evaluate(e=>e.scrollWidth>e.clientWidth+1))throw Error('Scene overflow '+width);if(width===390)await p.locator('.story-scene').screenshot({path:'audit-screenshots/lighthouse-story-scene.png',animations:'disabled'});await p.click('#storySceneSkip')}
await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));await p.click('#expeditionSail');await p.locator('.story-scene img').evaluateAll(xs=>Promise.all(xs.map(i=>i.decode())));await p.locator('.story-scene').screenshot({path:'audit-screenshots/voyage-story-scene.png',animations:'disabled'});await p.waitForFunction(()=>DEUTSCH_JOURNEY.island===1,{},{timeout:6000});if(await p.locator('dialog.story-scene').count())throw Error('Automatic completion leaked dialog');await p.click('#lighthouseCelebrate');await p.evaluate(()=>setMode('words'));if(await p.locator('dialog.story-scene').count())throw Error('Navigation did not cancel scene');await p.click('#learningTab');if(await p.evaluate(()=>JSON.stringify([profileStorage.getItem('deutsch16_journey_v1'),profileStorage.getItem('deutsch16_journey_village_v1')])!==sessionStorage.getItem('storyGrades')))throw Error('Scene rewrote rewards');
await p.emulateMedia({reducedMotion:'reduce'});await p.evaluate(()=>DEUTSCH_JOURNEY.select(0));await p.click('#expeditionSail');if(await p.locator('dialog.story-scene').count()||await p.evaluate(()=>DEUTSCH_JOURNEY.island)!==1)throw Error('Reduced motion did not bypass voyage');await p.click('#lighthouseCelebrate');if(await p.locator('dialog.story-scene').count())throw Error('Reduced motion did not bypass celebration');await p.emulateMedia({reducedMotion:'no-preference'});await p.evaluate(()=>{document.documentElement.lang='en';DEUTSCH_JOURNEY.select(0)});await p.click('#expeditionSail');if(await p.locator('#storySceneTitle').innerText()!=='Sailing to a new island!')throw Error('English missing');await p.click('#storySceneSkip');if(errors.length)throw Error(errors.join(';'));console.log('PASS story scenes: voyage/celebration, original images, focus/skip/Escape/automatic completion, cancellation, reduced motion, responsive layouts, localization and unchanged rewards');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
